54	/**
55	 * Gestione asset di un singolo record (digital-hub #16).
56	 *
57	 * Page record-scoped, full-width, fuori dalla navigazione: si raggiunge solo
58	 * dall'azione {@see \AtrioTeam\DigitalHub\Assets\Filament\Actions\ManageAssetsAction}
59	 * nella tabella di una resource. La route porta owner via coppia polimorfica
60	 * (morph alias + chiave): `/assets/{ownerType}/{owner}`, così la pagina è
61	 * generica per qualunque modello che usa il trait HasAssets, non solo Product.
62	 *
63	 * Lo stato dell'UI (folder attiva, ecc.) sarà aggiunto negli step successivi
64	 * di #16a; qui c'è solo lo scheletro navigabile.
65	 */
66	class AssetManager extends Page implements HasActions
67	{
68	    use InteractsWithActions;
69	
70	    protected static string|BackedEnum|null $navigationIcon = Heroicon::OutlinedFolderOpen;
71	
72	    protected static ?string $slug = 'assets';
73	
74	    protected string $view = 'digital-hub::filament.pages.asset-manager';
75	
76	    protected Width|string|null $maxContentWidth = Width::Full;
77	
78	    /**
79	     * Layout "base" (solo body, niente sidebar/topbar): la pagina è un editor di
80	     * asset a tutto schermo, presentato come un "finto modal" che si chiude con la
81	     * X tornando al catalogo (vedi blade). Il layout base include comunque gli
82	     * stili/script Filament e il componente notifiche, quindi toast e modali delle
83	     * action continuano a funzionare.
84	     */
85	    protected static string $layout = 'filament-panels::components.layout.base';
86	
87	    /** icona di "sposta", usata per file e cartelle */
88	    protected Heroicon $moveActionIcon = Heroicon::OutlinedArrowUpOnSquareStack;
89	
90	    /** Morph alias del record proprietario (es. `product`). */
91	    public string $ownerType;
92	
93	    /** Chiave primaria del record proprietario. */
94	    public int|string $ownerKey;
95	
96	    /** Folder attualmente selezionata; null = root (tutti gli asset del record). */
97	    public ?int $activeFolderId = null;
98	
99	    /**
100	     * URL della lista da cui si è arrivati (catturato dal Referer alla mount),
101	     * per il link "indietro". null se assente o non locale. È public così
102	     * sopravvive alle update Livewire successive (la mount gira una sola volta).
103	     */
104	    public ?string $returnUrl = null;
105	
106	    /**
107	     * Id dei media selezionati per le azioni multiple (checkbox sulle card).
108	     * @var array<int, int|string>
109	     */
110	    public array $selectedAssetIds = [];
111	
112	    /** URL dell'ultimo share creato, mostrato nel modal "share-link" (22g). */
113	    public ?string $lastShareUrl = null;
114	
115	    /**
116	     * Cache per-request del record risolto (privata: non serializzata da Livewire).
117	     * @var (Model&OwnsAssets)|null
118	     */
119	    private ?Model $ownerModel = null;
120	
121	    /**
122	     * Cache per-request delle folder del record (privata: non serializzata da Livewire).
123	     * @var null|EloquentCollection<int,AssetFolder>
124	     */
125	    private ?EloquentCollection $folderCache = null;
126	
127	    #[Override]
128	    public static function getRoutePath(Panel $panel): string
129	    {
130	        return '/assets/{ownerType}/{owner}';
131	    }
132	
133	    public static function shouldRegisterNavigation(): bool
134	    {
135	        return false;
136	    }
137	
138	    /**
139	     * I parametri di route (ownerType, owner) sono iniettati da Livewire.
140	     */
141	    public function mount(string $ownerType, int|string $owner): void
142	    {
143	        $this->ownerType = $ownerType;
144	        $this->ownerKey = $owner;
145	
146	        // valida subito: record risolvibile e dotato del trait HasAssets
147	        $this->resolveOwner();
148	
149	        // la lista di provenienza (con i suoi filtri, es. sottocategoria) è
150	        // esattamente la pagina che ha linkato qui: la prendiamo dal Referer.
151	        // Fallback (link diretto/tab nuova, niente referer): la lista della
152	        // resource del record, senza filtri.
153	        $this->returnUrl = $this->resolveReturnUrl(request()->headers->get('referer'))
154	            ?? $this->resourceIndexUrl();
155	    }
156	
157	    /**
158	     * Valida l'URL di ritorno: accetta solo URL dello stesso host dell'app (no
159	     * open redirect verso domini esterni) e scarta l'auto-riferimento alla
160	     * pagina asset stessa (es. reload). null se non valido.
161	     */
162	    private function resolveReturnUrl(?string $url): ?string
163	    {
164	        if (! is_string($url) || $url === '') {
165	            return null;
166	        }
167	
168	        $host = parse_url($url, PHP_URL_HOST);
169	        if ($host !== null && $host !== request()->getHost()) {
170	            return null;
171	        }
172	
173	        // non puntare a sé stessa (la pagina asset): eviterebbe un "indietro" che non torna indietro
174	        if (str_contains((string) parse_url($url, PHP_URL_PATH), '/assets/')) {
175	            return null;
176	        }
177	
178	        return $url;
179	    }
180	
181	    /**
182	     * URL della lista (index) della resource Filament del record, da usare come
183	     * fallback quando manca un Referer valido. null se il record non ha una
184	     * resource registrata nel pannello o l'URL non è risolvibile.
185	     */
186	    private function resourceIndexUrl(): ?string
187	    {
188	        /** @var class-string<\Filament\Resources\Resource>|null $resource */
189	        $resource = \Filament\Facades\Filament::getModelResource($this->resolveOwner());
190	        if ($resource === null) {
191	            return null;
192	        }
193	
194	        try {
195	            $url = $resource::getUrl('index');
196	
197	            return $url ?: null;
198	        } catch (\Throwable) {
199	            return null;
200	        }
201	    }
202	
203	    /**
204	     * Risolve il record proprietario dalla coppia (morph alias, chiave).
205	     * 404 se il tipo non è mappato, il record non esiste o non è OwnsAssets.
206	     *
207	     * @return Model&OwnsAssets
208	     */
209	    public function resolveOwner(): Model
210	    {
211	        if ($this->ownerModel !== null) {
212	            return $this->ownerModel;
213	        }
214	
215	        $class = Relation::getMorphedModel($this->ownerType) ?? $this->ownerType;
216	        abort_unless(class_exists($class), 404);
217	
218	        /** @var class-string<Model> $class */
219	        $record = $class::query()->find($this->ownerKey);
220	        abort_unless($record instanceof OwnsAssets, 404);
221	
222	        return $this->ownerModel = $record;
223	    }
224	
225	    #[Override]
226	    public function getTitle(): string|Htmlable
227	    {
228	        $owner = $this->resolveOwner();
229	        $name = $owner->getAttribute('name');
230	        $key = $owner->getKey();
231	        $label = is_string($name) && $name !== ''
232	            ? $name
233	            : '#' . (is_scalar($key) ? (string) $key : '');
234	
235	        return (string) __('digital-hub::assets.title_for', ['owner' => $label]);
236	    }
237	
238	    /**
239	     * Nessun heading di pagina Filament: il titolo è renderizzato dalla barra del
240	     * finto modal nel blade. Tornando '' (vuoto) il componente di pagina non
241	     * disegna affatto l'header, evitando il doppione.
242	     */
243	    #[Override]
244	    public function getHeading(): string|Htmlable
245	    {
246	        return '';
247	    }
248	
249	    /**
250	     * Tutte le folder del record, caricate una sola volta per request.
251	     *
252	     * @return EloquentCollection<int, AssetFolder>
253	     */
254	    public function allFolders(): EloquentCollection
255	    {
256	        if ($this->folderCache !== null) {
257	            return $this->folderCache;
258	        }
259	
260	        return $this->folderCache = $this->resolveOwner()->allAssetFolders();
261	    }
262	
263	    /**
264	     * Seleziona la folder attiva (null = root). Ignora id non appartenenti al
265	     * record (es. manomissione del payload Livewire).
266	     */
267	    public function selectFolder(?int $folderId): void
268	    {
269	        // cambiando vista la selezione corrente non ha più senso
270	        $this->selectedAssetIds = [];
271	
272	        if ($folderId === null) {
273	            $this->activeFolderId = null;
274	
275	            return;
276	        }
277	
278	        if ($this->allFolders()->firstWhere('id', $folderId) !== null) {
279	            $this->activeFolderId = $folderId;
280	        }
281	    }
282	
283	    /**
284	     * Svuota la selezione corrente (pulsante "Annulla selezione").
285	     */
286	    public function clearAssetSelection(): void
287	    {
288	        $this->selectedAssetIds = [];
289	    }
290	
291	    /**
292	     * Seleziona tutti gli asset attualmente visibili nella vista corrente
293	     * (pulsante "Seleziona tutti", disponibile dopo la prima selezione).
294	     */
295	    public function selectAllAssets(): void
296	    {
297	        $this->selectedAssetIds = $this->getAssets()
298	            ->map(function (Media $media): string {
299	                $key = $media->getKey();
300	
301	                return is_int($key) || is_string($key) ? (string) $key : '';
302	            })
303	            ->all();
304	    }
305	
306	    /**
307	     * Sposta un media in una folder (o root) via drag-drop sull'albero (#16b).
308	     * `$mediaId` arriva come stringa dal dataTransfer; `$folderId` null = root.
309	     */
310	    public function moveAssetToFolder(mixed $mediaId, ?int $folderId): void
311	    {
312	        $media = $this->findOwnedMedia($mediaId);
313	        if ($media === null) {
314	            return;
315	        }
316	
317	        if ($folderId !== null && $this->findOwnedFolder($folderId) === null) {
318	            $folderId = null;
319	        }
320	
321	        $media->setAttribute('asset_folder_id', $folderId);
322	        $media->save();
323	
324	        Notification::make()->success()->title(__('digital-hub::assets.asset_moved'))->send();
325	    }
326	
327	    /**
328	     * Riordina un gruppo di folder fratelli via drag-drop nell'albero (#16b).
329	     * Riceve gli id nel nuovo ordine (da SortableJS) e riassegna `sort` per
330	     * posizione. Gli id estranei al record sono ignorati.
331	     *
332	     * @param array<int, int|string> $orderedIds
333	     */
334	    public function reorderFolders(array $orderedIds): void
335	    {
336	        foreach (array_values($orderedIds) as $index => $id) {
337	            $folder = $this->findOwnedFolder($id);
338	            if ($folder === null) {
339	                continue;
340	            }
341	
342	            if ($folder->sort !== $index) {
343	                $folder->sort = $index;
344	                $folder->save();
345	            }
346	        }
347	
348	        $this->folderCache = null;
349	    }
350	
351	    /**
352	     * Albero annidato delle folder del record per il pannello sinistro.
353	     * `children` è ricorsivamente la stessa struttura (non esprimibile come tipo
354	     * ricorsivo preciso in PHPDoc, quindi `mixed`).
355	     *
356	     * @return array<int, array{folder: AssetFolder, children: mixed}>
357	     */
358	    public function getFolderTree(): array
359	    {
360	        return $this->buildTree(null);
361	    }
362	
363	    /**
364	     * @return array<int, array{folder: AssetFolder, children: mixed}>
365	     */
366	    private function buildTree(?int $parentId): array
367	    {
368	        return $this->allFolders()
369	            ->where('parent_id', $parentId)
370	            ->map(fn (AssetFolder $folder): array => [
371	                'folder' => $folder,
372	                'children' => $this->buildTree($folder->id),
373	            ])
374	            ->values()
375	            ->all();
376	    }
377	
378	    /**
379	     * Sottocartelle dirette della folder attiva, da mostrare come tile nel
380	     * pannello destro insieme ai file. Vuota in "Tutti gli asset" (root): lì la
381	     * vista resta l'aggregato piatto di soli file.
382	     *
383	     * @return \Illuminate\Support\Collection<int, AssetFolder>
384	     */
385	    public function getSubfolders(): \Illuminate\Support\Collection
386	    {
387	        if ($this->activeFolderId === null) {
388	            return new \Illuminate\Support\Collection();
389	        }
390	
391	        return $this->allFolders()
392	            ->where('parent_id', $this->activeFolderId)
393	            ->values();
394	    }
395	
396	    /**
397	     * Catena dalla root alla folder attiva, per il breadcrumb. Vuota se siamo
398	     * in root. Se l'id attivo non esiste più (folder eliminata), resetta a root.
399	     *
400	     * @return list<AssetFolder>
401	     */
402	    public function getBreadcrumbTrail(): array
403	    {
404	        if ($this->activeFolderId === null) {
405	            return [];
406	        }
407	
408	        $folders = $this->allFolders();
409	        $trail = [];
410	        $id = $this->activeFolderId;
411	
412	        while ($id !== null) {
413	            $folder = $folders->firstWhere('id', $id);
414	            if (! $folder instanceof AssetFolder) {
415	                // folder eliminata sotto i piedi: torna a root
416	                $this->activeFolderId = null;
417	
418	                return [];
419	            }
420	
421	            array_unshift($trail, $folder);
422	            $id = $folder->parent_id;
423	        }
424	
425	        return $trail;
426	    }
427	
428	    /**
429	     * Media mostrati nel pannello destro. Sulla voce "Tutti gli asset"
430	     * (nessuna folder attiva) è la vista aggregata di TUTTI i media del record;
431	     * su una folder, i soli media diretti di quella folder.
432	     *
433	     * @return \Illuminate\Support\Collection<int, \Spatie\MediaLibrary\MediaCollections\Models\Media>
434	     */
435	    public function getAssets(): \Illuminate\Support\Collection
436	    {
437	        $owner = $this->resolveOwner();
438	
439	        if ($this->activeFolderId === null) {
440	            return $owner->allAssets();
441	        }
442	
443	        return $owner->assetsInFolder($this->findOwnedFolder($this->activeFolderId));
444	    }
445	
446	    /**
447	     * Percorso completo (root → cartella) del media, per il badge nella vista
448	     * aggregata "Tutti gli asset". Es. "Documenti / 2024".
449	     * null = media non assegnato a nessuna folder.
450	     */
451	    public function assetFolderPath(Media $media): ?string
452	    {
453	        $id = $media->getAttribute('asset_folder_id');
454	        if (! is_numeric($id)) {
455	            return null;
456	        }
457	
458	        $folders = $this->allFolders();
459	        $names = [];
460	        $current = (int) $id;
461	        $guard = 0;
462	
463	        while ($current !== null) {
464	            $folder = $folders->firstWhere('id', $current);
465	            if (! $folder instanceof AssetFolder) {
466	                break;
467	            }
468	
469	            array_unshift($names, $folder->name);
470	            $current = $folder->parent_id;
471	
472	            if (++$guard > AssetFolder::MAX_DEPTH + 1) {
473	                break; // safety contro catene anomale
474	            }
475	        }
476	
477	        return $names === [] ? null : implode(' / ', $names);
478	    }
479	
480	    // -- CRUD folder (#16a step 3) ------------------------------------------
481	
482	    /**
483	     * Crea una folder sotto la folder attiva (root se nessuna selezionata).
484	     * Le invarianti (profondità, owner, cicli) sono enforce dal model in saving.
485	     */
486	    public function createFolderAction(): Action
487	    {
488	        return Action::make('createFolder')
489	            ->label(__('digital-hub::assets.new_folder'))
490	            ->icon(Heroicon::OutlinedFolderPlus)
491	            ->modalHeading(fn (): string => $this->activeFolderId === null
492	                ? (string) __('digital-hub::assets.new_folder')
493	                : (string) __('digital-hub::assets.new_subfolder'))
494	            ->schema([
495	                TextInput::make('name')
496	                    ->label(__('digital-hub::assets.folder_name'))
497	                    ->required()
498	                    ->maxLength(255),
499	            ])
500	            ->action(function (array $data): void {
501	                $owner = $this->resolveOwner();
502	                $parent = $this->activeFolderId !== null
503	                    ? $this->findOwnedFolder($this->activeFolderId)
504	                    : null;
505	                $name = is_string($data['name']) ? $data['name'] : '';
506	
507	                try {
508	                    // createAssetFolder salva internamente: il saving hook del
509	                    // model applica le invarianti (profondità, owner, cicli).
510	                    $owner->createAssetFolder($name, $parent);
511	                } catch (ValidationException $e) {
512	                    Notification::make()->danger()->title($this->firstValidationMessage($e))->send();
513	
514	                    return;
515	                }
516	
517	                $this->folderCache = null;
518	                Notification::make()->success()->title(__('digital-hub::assets.folder_created'))->send();
519	            });
520	    }
521	
522	    /**
523	     * Rinomina una folder del record. `folder` (id) passato come argument.
524	     */
525	    public function renameFolderAction(): Action
526	    {
527	        return Action::make('renameFolder')
528	            ->label(__('digital-hub::assets.rename_folder'))
529	            ->icon(Heroicon::OutlinedPencilSquare)
530	            ->iconButton()
531	            ->modalHeading(__('digital-hub::assets.rename_folder'))
532	            ->fillForm(function (array $arguments): array {
533	                $folder = $this->findOwnedFolder($arguments['folder'] ?? null);
534	
535	                return ['name' => $folder?->name];
536	            })
537	            ->schema([
538	                TextInput::make('name')
539	                    ->label(__('digital-hub::assets.folder_name'))
540	                    ->required()
541	                    ->maxLength(255),
542	            ])
543	            ->action(function (array $arguments, array $data): void {
544	                $folder = $this->findOwnedFolder($arguments['folder'] ?? null);
545	                if ($folder === null) {
546	                    return;
547	                }
548	
549	                $folder->name = is_string($data['name']) ? $data['name'] : $folder->name;
550	
551	                if ($this->persistFolder($folder)) {
552	                    Notification::make()->success()->title(__('digital-hub::assets.folder_renamed'))->send();
553	                }
554	            });
555	    }
556	
557	    /**
558	     * Elimina una folder del record. Il model rifiuta la cancellazione se la
559	     * folder contiene sotto-cartelle o media (deleting hook → ValidationException),
560	     * qui intercettata e mostrata come notifica.
561	     */
562	    public function deleteFolderAction(): Action
563	    {
564	        return Action::make('deleteFolder')
565	            ->label(__('digital-hub::assets.delete_folder'))
566	            ->icon(Heroicon::OutlinedTrash)
567	            ->iconButton()
568	            ->color('danger')
569	            ->requiresConfirmation()
570	            ->modalHeading(__('digital-hub::assets.delete_folder_heading'))
571	            ->modalDescription(__('digital-hub::assets.delete_folder_confirmation'))
572	            ->action(function (array $arguments): void {
573	                $folder = $this->findOwnedFolder($arguments['folder'] ?? null);
574	                if ($folder === null) {
575	                    return;
576	                }
577	
578	                // Pre-check dello stesso invariante del deleting hook del model
579	                // (che resta la rete di sicurezza per i path non-UI): rifiuta se
580	                // la folder contiene sotto-cartelle o media.
581	                if ($folder->children()->exists() || $folder->media()->exists()) {
582	                    Notification::make()->danger()->title(__('digital-hub::asset_folders.cannot_delete_non_empty'))->send();
583	
584	                    return;
585	                }
586	
587	                $folder->delete();
588	
589	                if ($this->activeFolderId === $folder->id) {
590	                    $this->activeFolderId = null;
591	                }
