namespace AtrioTeam\DigitalHub\Assets\Filament\Pages;

use AtrioTeam\DigitalHub\Assets\Models\AssetShare;
use Filament\Pages\Page;
use Filament\Panel;
use Illuminate\Contracts\Support\Htmlable;
use Illuminate\Database\Eloquent\Collection;
use Illuminate\Validation\ValidationException;
use Override;
use Spatie\MediaLibrary\MediaCollections\Models\Media;

/**
 * Gallery pubblica di una condivisione esterna (digital-hub 22g).
 *
 * Page del panel guest `share` (vedi App\Providers\Filament\SharePanelProvider):
 * accessibile SENZA account via link `/share/{token}`. Risolve l'AssetShare dal
 * token (404 se sconosciuto/scaduto/vuoto), applica l'eventuale gate password e
 * mostra la gallery read-only: miniature (anteprima via signed URL temporanei),
 * metadati base (senza identità interne) e download (selezione o tutto) riusando
 * lo zip per token della 22e.
 */
class ShareGallery extends Page
{
    protected string $view = 'digital-hub::filament.pages.share-gallery';

    /** Share risolto dal token della route. */
    public AssetShare $share;

    /** Password inserita nel gate (transiente). */
    public ?string $password = null;

    /**
     * Id dei media selezionati per il download.
     *
     * @var array<int, int|string>
     */
    public array $selected = [];

    /** Route token-based: il path del panel è già `share` → `/share/{token}`. */
    #[Override]
    public static function getRoutePath(Panel $panel): string
    {
        return '/{token}';
    }

    public static function shouldRegisterNavigation(): bool
    {
        return false;
    }

    /**
     * Risolve lo share dal token (iniettato da Livewire come parametro di route).
     * 404 se il token è sconosciuto, lo share è scaduto/revocato o non ha media.
     */
    public function mount(string $token): void
    {
        $share = AssetShare::query()->where('token', $token)->first();

        abort_if($share === null || $share->isExpired(), 404);
        abort_if($share->media()->count() === 0, 404);

        $this->share = $share;
        $share->touchAccessed();
    }

    #[Override]
    public function getHeading(): string|Htmlable
    {
        return $this->share->name ?? __('digital-hub::assets.share_gallery_title');
    }

    /** Vero se la gallery è visibile: share senza password o già sbloccato in sessione. */
    public function isUnlocked(): bool
    {
        return ! $this->share->hasPassword()
            || session()->get($this->share->sessionUnlockKey()) === true;

